function parseThresholdStrings(thresholdStrings: string[] | undefined = []): Record<string, number> {
  const thresholds: Record<string, number> = {};

  thresholdStrings.forEach((str) => {
    const parts = str.split('=');
    if (parts.length !== 2) {
      throw new Error(`Malformed threshold "${str}": expected format <metric>=<min>`);
    }
    const [metricId, minStr] = parts;
    const min = Number.parseFloat(minStr);
    if (Number.isNaN(min)) {
      throw new Error(`Invalid threshold for metric "${metricId}": "${minStr}" is not a number`);
    }
    if (min < 0 || min > 1) {
      throw new Error(`Invalid threshold for metric "${metricId}": value ${min} is outside range [0, 1]`);
    }
    thresholds[metricId] = min;
  });

  return thresholds;
}

function runEvalCommand(options: EvalOptions) {
  assertFileExists(options.outputs);
  const dataset = (Eval.loadDataset as unknown as (config: unknown) => any)({
    outputsPath: options.outputs,
    referencesPath: options.references
  });
  const evaluations = (Eval.runEvaluations as unknown as (config: unknown) => any)({
    outputs: dataset.outputs,
    references: dataset.references
  });

  let thresholds: Record<string, number> = {};
  let thresholdValidation: { valid: boolean; validated?: Record<string, number>; errors?: string[] } | null = null;

  try {
    thresholds = parseThresholdStrings(options.threshold);
    thresholdValidation = (Eval.validateThresholds as unknown as (config: unknown) => any)(
      thresholds,
      evaluations
    );
    if (!thresholdValidation.valid) {
      log.error('Invalid threshold configuration.');
      thresholdValidation.errors?.forEach((error) => {
        console.error(`  - ${error}`);
      });
      process.exit(2);
    }
  } catch (error) {
    log.error('Threshold parsing error.', {
      error: error instanceof Error ? error.message : String(error)
    });
    process.exit(2);
  }

  const report = (Eval.generateReport as unknown as (config: unknown) => any)({
    evaluations,
    outputsPath: dataset.outputsPath,
    referencesPath: dataset.referencesPath,
    thresholds: thresholdValidation?.validated ?? thresholds
  });
  const resolvedPath = (Eval.writeReport as unknown as (config: unknown) => string)({
    report,
    format: options.format ?? 'json',
    reportPath: options.report
  });
  log.success('Evaluation report generated.', { path: resolvedPath });

  if (report.passed === false) {
    process.exit(1);
  }
}

