    fs.writeFileSync(outputsPath, JSON.stringify(['Hello', 'World'], null, 2));
    fs.writeFileSync(referencesPath, JSON.stringify(['hello', 'world'], null, 2));

    const dataset = loadDataset({ outputsPath, referencesPath });
    expect(dataset.outputs).toEqual(['Hello', 'World']);
    expect(dataset.references).toEqual(['hello', 'world']);
  });

  it('runs default evaluations', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello', 'friendly world'],
      references: ['hello', 'friendly world']
    });
    const exact = evaluations.find((metric) => metric.id === 'exact_match');
    const toxicity = evaluations.find((metric) => metric.id === 'toxicity');

    expect(exact.score).toBeCloseTo(1, 4);
    expect(toxicity.score).toBe(1);
  });

  it('generates and writes report', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: ['hello']
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      generatedAt: '2024-01-01T00:00:00.000Z'
    });
    expect(report.metadata.totalSamples).toBe(1);

    const dir = createTempDir();
    const jsonPath = writeReport({
      report,
      format: 'json',
      reportPath: path.join(dir, 'report.json')
    });
    const markdownPath = writeReport({
      report,
      format: 'markdown',
      reportPath: path.join(dir, 'report.md')
    });

    expect(fs.existsSync(jsonPath)).toBe(true);
    expect(fs.existsSync(markdownPath)).toBe(true);
  });

  it('validates thresholds correctly', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello', 'World'],
      references: ['hello', 'world']
    });

    const valid = validateThresholds({ exact_match: 0.5, toxicity: 0.8 }, evaluations);
    expect(valid.valid).toBe(true);
    expect(valid.validated).toEqual({ exact_match: 0.5, toxicity: 0.8 });
  });

  it('rejects unknown metric ids', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: ['hello']
    });

    const invalid = validateThresholds({ unknown_metric: 0.5 }, evaluations);
    expect(invalid.valid).toBe(false);
    expect(invalid.errors).toContainEqual(expect.stringContaining('Unknown metric "unknown_metric"'));
  });

  it('rejects thresholds outside range [0, 1]', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: ['hello']
    });

    const negative = validateThresholds({ exact_match: -0.1 }, evaluations);
    expect(negative.valid).toBe(false);
    expect(negative.errors[0]).toContain('expected a number between 0 and 1');

    const tooHigh = validateThresholds({ exact_match: 1.5 }, evaluations);
    expect(tooHigh.valid).toBe(false);
    expect(tooHigh.errors[0]).toContain('expected a number between 0 and 1');
  });

  it('evaluates thresholds against metrics', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello', 'hello'],
      references: ['hello', 'hello']
    });

    const result = evaluateThresholds({ exact_match: 0.9 }, evaluations);
    expect(result.passed).toBe(true);
    expect(result.thresholds[0]).toEqual({
      metric: 'exact_match',
      min: 0.9,
      score: expect.any(Number),
      passed: true
    });
  });

  it('fails threshold when score below minimum', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello', 'Goodbye'],
      references: ['hello', 'hello']
    });

    const result = evaluateThresholds({ exact_match: 0.9 }, evaluations);
    expect(result.passed).toBe(false);
    expect(result.thresholds[0].passed).toBe(false);
  });

  it('fails threshold when metric has no score', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello']
    });

    const result = evaluateThresholds({ exact_match: 0.5 }, evaluations);
    expect(result.passed).toBe(false);
    expect(result.thresholds[0].passed).toBe(false);
    expect(result.thresholds[0].score).toBe(null);
  });

  it('includes thresholds in generated report', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello', 'hello'],
      references: ['hello', 'hello']
    });

    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      thresholds: { exact_match: 0.5 },
      generatedAt: '2024-01-01T00:00:00.000Z'
    });

    expect(report.passed).toBe(true);
    expect(report.thresholds).toBeDefined();
    expect(report.thresholds).toHaveLength(1);
    expect(report.thresholds[0]).toEqual({
      metric: 'exact_match',
      min: 0.5,
      score: expect.any(Number),
      passed: true
    });
  });

  it('does not include thresholds in report when none provided', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: ['hello']
    });

    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      generatedAt: '2024-01-01T00:00:00.000Z'
    });

    expect(report.passed).toBeUndefined();
    expect(report.thresholds).toBeUndefined();
  });
});

